/**
 * Signature interactive for the Diffusion station: scrub a real SD1.5
 * sampling run, frame by frame — three seeds, decoded pixels or the raw
 * 64×64 latent, with a filmstrip of every state. Frames generated by
 * scripts/generate_diffusion_frames.py from the ComfyUI checkpoint.
 */
import { useEffect, useState } from "react";
import { InstrumentPanel } from "@/components/site/InstrumentPanel";

const STEPS = 21; // pure noise + 20 sampling states
const SEEDS = 3;
const BASE = "/data/diffusion";

type View = "state" | "guess" | "latent";

const VIEWS: { key: View; name: string; note: string }[] = [
  { key: "state", name: "the canvas", note: "x_t — what the latent actually holds right now" },
  { key: "guess", name: "the guess", note: "x̂₀ — the model's current prediction of the finish" },
  { key: "latent", name: "raw latent", note: "the 64×64×4 tensor itself, three channels as rgb" },
];

const frameSrc = (seed: number, step: number, view: View) =>
  view === "latent"
    ? `${BASE}/seed${seed}/latent${step}.png`
    : `${BASE}/seed${seed}/${view === "state" ? "step" : "guess"}${step}.webp`;

/* seeds whose frames have already been preloaded (module-level, like the
   attention lens's cache — switching back to a seed must be free) */
const preloaded = new Set<number>();

export function DenoisingDeck() {
  const [seed, setSeed] = useState(0);
  const [step, setStep] = useState(0);
  const [view, setView] = useState<View>("state");
  const [playing, setPlaying] = useState(false);

  // preload the active seed's frames once so scrubbing never flashes
  useEffect(() => {
    if (preloaded.has(seed)) return;
    preloaded.add(seed);
    for (let i = 0; i < STEPS; i++) {
      for (const v of VIEWS) new Image().src = frameSrc(seed, i, v.key);
    }
  }, [seed]);

  // autoplay through the run
  useEffect(() => {
    if (!playing) return;
    let s = 0;
    setStep(0);
    const id = setInterval(() => {
      s = Math.min(s + 1, STEPS - 1);
      setStep(s);
      if (s >= STEPS - 1) setPlaying(false);
    }, 160);
    return () => clearInterval(id);
  }, [playing]);

  return (
    <InstrumentPanel
      label="The denoising deck — one real SD1.5 run, every state kept"
      live={playing}
      readout={`state ${step} / ${STEPS - 1} · ${VIEWS.find((v) => v.key === view)!.name}`}
    >
      <div className="flex flex-wrap items-start justify-center gap-x-8 gap-y-4">
        {/* main viewer */}
        <div>
          <img
            src={frameSrc(seed, step, view)}
            alt={`Stable Diffusion denoising, state ${step} of ${STEPS - 1}: a lighthouse oil painting emerging from noise (seed ${String.fromCharCode(65 + seed)}, ${VIEWS.find((v) => v.key === view)!.name} view)`}
            width={352}
            height={352}
            className="block h-auto max-w-full border border-border"
            style={view === "latent" ? { imageRendering: "pixelated" } : undefined}
            draggable={false}
          />
          <label className="label-tech mt-3 flex items-center gap-3">
            <span className="whitespace-nowrap">noise → image</span>
            <input
              type="range"
              min={0}
              max={STEPS - 1}
              value={step}
              onChange={(e) => {
                setPlaying(false);
                setStep(Number(e.target.value));
              }}
              className="w-full"
              style={{ accentColor: "var(--station)" }}
            />
          </label>
        </div>

        {/* filmstrip + controls */}
        <div className="w-[300px] max-w-full">
          <p className="label-tech mb-1.5">every state of this run</p>
          <div className="grid grid-cols-7 gap-1">
            {Array.from({ length: STEPS }, (_, i) => (
              <button
                key={i}
                onClick={() => {
                  setPlaying(false);
                  setStep(i);
                }}
                className="block border p-0"
                style={{
                  borderColor: i === step ? "var(--station)" : "var(--color-border)",
                  opacity: i === step ? 1 : 0.75,
                }}
              >
                <img
                  src={frameSrc(seed, i, view)}
                  alt={`thumbnail of denoising state ${i} of ${STEPS - 1}`}
                  width={38}
                  height={38}
                  className="block"
                  style={view === "latent" ? { imageRendering: "pixelated" } : undefined}
                  draggable={false}
                />
              </button>
            ))}
          </div>

          <div className="mt-4 flex flex-wrap items-center gap-1.5">
            <button className="btn-tech" onClick={() => setPlaying((p) => !p)}>
              {playing ? "stop" : "▶ run the loop"}
            </button>
            <span className="mx-1 h-4 w-px bg-border" />
            {Array.from({ length: SEEDS }, (_, k) => (
              <button
                key={k}
                className="btn-tech"
                data-active={seed === k}
                onClick={() => setSeed(k)}
              >
                seed {String.fromCharCode(65 + k)}
              </button>
            ))}
            <span className="mx-1 h-4 w-px bg-border" />
            {VIEWS.map((v) => (
              <button
                key={v.key}
                className="btn-tech"
                data-active={view === v.key}
                onClick={() => setView(v.key)}
              >
                {v.name}
              </button>
            ))}
          </div>
          <p className="label-tech mt-3 normal-case tracking-normal">
            {VIEWS.find((v) => v.key === view)!.note}. same prompt, same model — only the starting
            noise differs between seeds.
          </p>
        </div>
      </div>
      <p className="label-tech mt-3 text-center normal-case tracking-normal">
        prompt: &ldquo;a lighthouse on a rocky cliff at dusk, dramatic golden clouds, crashing
        waves, oil painting&rdquo; · 20 ddim steps · cfg 7.5
      </p>
    </InstrumentPanel>
  );
}
